const socket=io(),$=s=>document.querySelector(s);let gifts=[],selected=null,mapping={},leaders=[];
const actions=[['JOIN_MARCH','Safa Katıl'],['RANK_SIPAHI','Sipahi Terfisi'],['RANK_SANCAKTAR','Sancaktar'],['EVENT_MEHTER','Mehter Coşkusu'],['EVENT_CATAPULT','Mancınık'],['RANK_CAVALRY','Atlı Akıncı'],['EVENT_SEAL','Sadrazam Mührü'],['RANK_VIZIER','Başkomutan / Vezir']];
$('#actions').innerHTML=actions.map(a=>`<button data-action="${a[0]}">${a[1]}</button>`).join('');
async function load(){const r=await fetch('/api/gifts');gifts=await r.json();renderGifts();const s=await(await fetch('/api/state')).json();mapping=s.mapping||{};renderLeaders(s.leaderboard||[])}
function renderGifts(){const q=$('#search').value.toLower?.()||'',min=+$('#filter').value;$('#giftsList').innerHTML=gifts.filter(g=>(g.name||'').toLowerCase().includes(q)&&g.diamonds>=min).map(g=>`<div class="gift" data-id="${g.id}"><img src="${g.image||''}" onerror="this.style.display='none'"><div><b>${g.name||'Hediye '+g.id}</b><br><small>ID ${g.id}</small></div><small>${g.diamonds} 💎</small></div>`).join('')||'<small>Katalog henüz yayınla çekilmedi</small>';document.querySelectorAll('.gift').forEach(e=>e.onclick=()=>{selected=e.dataset.id;document.querySelectorAll('.gift').forEach(x=>x.style.outline='');e.style.outline='1px solid #c99a50'})}
$('#search').oninput=renderGifts;$('#filter').onchange=renderGifts;
$('#actions').onclick=e=>{if(!e.target.dataset.action||!selected)return;mapping[selected]=e.target.dataset.action;fetch('/api/mapping',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(mapping)});e.target.textContent+=' ✓'};
socket.on('status',s=>{$('#status').textContent=s.state;$('#detail').textContent=s.message||s.state;$('#dot').style.background=s.state==='Bağlandı'?'#57c78a':/Hata/.test(s.state)?'#d45a4c':'#b7a876'});
socket.on('stats',t=>{$('#viewers').textContent=t.viewers||0;$('#likes').textContent=t.likes||0;$('#gifts').textContent=t.gifts||0});socket.on('gifts',g=>{gifts=g||[];renderGifts()});socket.on('leaderboard',renderLeaders);
function renderLeaders(list){$('#leaders').innerHTML=(list||[]).sort((a,b)=>(b.score||0)-(a.score||0)).slice(0,12).map(p=>`<div class="leader"><img src="${p.avatar?'/api/avatar?url='+encodeURIComponent(p.avatar):''}" onerror="this.style.display='none'"><div>${p.nickname}<br><small>${p.uniqueId}</small></div><b class="rank">${p.rank||'Nefer'}</b></div>`).join('')||'<small>Henüz oyuncu yok</small>'}
$('#connect').onclick=()=>fetch('/api/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#username').value})});$('#disconnect').onclick=()=>fetch('/api/disdisconnect',{method:'POST'}).catch(()=>fetch('/api/disconnect',{method:'POST'}));
$('#reset').onclick=()=>{if(confirm('Yeni tur başlatılsın mı?'))fetch('/api/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{"action":"RESET_TURN"}'})};
document.querySelectorAll('.sim button').forEach(b=>b.onclick=()=>{const names=['Mustafa Alp','Ayşe Sultan','Selçuklu','Arslan Bey'];fetch('/api/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:b.dataset.action,nickname:names[Math.floor(Math.random()*names.length)],uniqueId:'test-'+Date.now(),profilePictureUrl:''})})});
function settings(){socket.emit('settings',{});fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({volume:+$('#volume').value,muted:$('#mute').checked,safeZones:$('#safe').checked})})}
$('#volume').oninput=()=>{$('#volv').textContent=$('#volume').value+'%';settings()};$('#mute').onchange=settings;$('#safe').onchange=settings;
$('#drum').onclick=()=>document.querySelectorAll('.sim button')[1].click();
$('#vertical').onclick=()=>socket.emit('aspect','9:16');$('#horizontal').onclick=()=>socket.emit('aspect','16:9');
load();
